const expected = <preparerevision.result.update_files>;
const iterations = <writerevisionfiles.results>;
const commits = [];
const errors = [];

for (let i = 0; i < expected.length; i++) {
  const outputs = Array.isArray(iterations?.[i]) ? iterations[i] : [];
  const apiOutput = outputs.find((item) => item && Object.prototype.hasOwnProperty.call(item, 'data'));
  const status = Number(apiOutput?.status ?? 0);
  const data = apiOutput?.data;
  if (status !== 200 || !data?.content?.sha || !data?.commit?.sha) {
    errors.push(`Запись не подтверждена для ${expected[i].path}: HTTP ${status}`);
    continue;
  }
  commits.push({path: expected[i].path, file_sha: String(data.content.sha), commit_sha: String(data.commit.sha)});
}

return {
  valid: errors.length === 0 && commits.length === expected.length && expected.length > 0,
  status: errors.length === 0 && commits.length === expected.length ? 'revised' : 'partial_write',
  errors,
  owner: <validateinput.result.owner>,
  repo: <validateinput.result.repo>,
  branch: <validateinput.result.branch>,
  pr_number: <validateinput.result.pr_number>,
  artifact_version: <validateinput.result.artifact_version>,
  attempt: <validateinput.result.attempt>,
  next_attempt: Number(<validateinput.result.attempt>) + 1,
  commits,
  files_written: commits.map((item) => item.path),
  protected_findings: <normalizedecision.result.protected_findings>,
  message: 'Ветка PR обновлена. Следующим блоком Workflow 04 будет явно запущен повторный CI.'
};

function parseJson(value) {
  if (value && typeof value === 'object') return value;
  if (typeof value !== 'string' || !value.trim()) return null;
  try { return JSON.parse(value); } catch (_) { return null; }
}

const errors = [];
const summary = parseJson(<getcisummary.data>);
const manifest = parseJson(<getmanifest.data>);
const expectedRepository = `${String(<validateinput.result.owner> ?? '')}/${String(<validateinput.result.repo> ?? '')}`;
const expectedSha = String(<validateinput.result.commit_sha> ?? '').toLowerCase();
const expectedVersion = String(<validateinput.result.artifact_version> ?? '');

if (Number(<getcisummary.status>) !== 200 || !summary || Array.isArray(summary)) {
  errors.push('ci-summary.json не получен или не является JSON-объектом');
}
if (Number(<getmanifest.status>) !== 200 || !manifest || Array.isArray(manifest)) {
  errors.push('artifact-manifest.json не получен или не является JSON-объектом');
}

const summaryRepository = String(summary?.repository ?? '');
const manifestRepository = String(manifest?.repository ?? '');
if (!summaryRepository || summaryRepository !== expectedRepository) {
  errors.push(`Репозиторий в ci-summary (${summaryRepository || 'не указан'}) не совпадает с ${expectedRepository}`);
}
if (!manifestRepository || manifestRepository !== expectedRepository) {
  errors.push(`Репозиторий в manifest (${manifestRepository || 'не указан'}) не совпадает с ${expectedRepository}`);
}

const summarySha = String(summary?.commit?.sha ?? summary?.commit_sha ?? '').toLowerCase();
const manifestSha = String(manifest?.commit_sha ?? '').toLowerCase();
if (!summarySha || summarySha !== expectedSha) {
  errors.push(`Commit в ci-summary (${summarySha || 'не указан'}) не совпадает с ${expectedSha}`);
}
if (!manifestSha || manifestSha !== expectedSha) {
  errors.push(`Commit в manifest (${manifestSha || 'не указан'}) не совпадает с ${expectedSha}`);
}

const summaryVersion = String(summary?.artifact?.version ?? summary?.artifact_version ?? '');
const manifestVersion = String(manifest?.artifact_version ?? '');
if (!summaryVersion || summaryVersion !== expectedVersion) {
  errors.push(`Версия в ci-summary (${summaryVersion || 'не указана'}) не совпадает с ${expectedVersion}`);
}
if (!manifestVersion || manifestVersion !== expectedVersion) {
  errors.push(`Версия в manifest (${manifestVersion || 'не указана'}) не совпадает с ${expectedVersion}`);
}

const manifestFiles = Array.isArray(manifest?.files) ? manifest.files : [];
if (!Array.isArray(manifest?.files)) errors.push('В artifact-manifest.json отсутствует массив files');

const names = new Set(
  manifestFiles
    .map((item) => typeof item === 'string' ? item : item?.name)
    .map((item) => String(item ?? '').trim())
    .filter((item) => /^[A-Za-z0-9._-]+$/.test(item))
);

for (const required of ['ci-summary.json', 'findings.json', 'test-report.md']) {
  if (!names.has(required)) errors.push(`В manifest отсутствует обязательный артефакт ${required}`);
}

function choose(candidates) {
  for (const candidate of candidates) {
    if (names.has(candidate)) return candidate;
  }
  return '';
}

// Если специализированного журнала нет (например, этап неприменим к типу
// проекта), используется обязательный сводный test-report.md. Поэтому GET не
// падает с 404 и один Workflow 04 работает для разных профилей.
const unitEvidence = choose(['pytest.log', 'unit.log', 'test.log', 'test-report.md']);
const staticEvidence = choose(['semgrep.log', 'semgrep.json', 'sast.log', 'static-analysis.log', 'test-report.md']);
const dynamicEvidence = choose([
  'cli-smoke.log',
  'runtime-smoke.log',
  'runtime.log',
  'zap.json',
  'zap.log',
  'dast.log',
  'dynamic-analysis.log',
  'test-report.md'
]);

if (!unitEvidence) errors.push('Не найдено доказательство этапа тестирования');
if (!staticEvidence) errors.push('Не найдено доказательство статического анализа');
if (!dynamicEvidence) errors.push('Не найдено доказательство динамического анализа или сводный отчёт');

return {
  valid: errors.length === 0,
  status: errors.length === 0 ? 'evidence_set_valid' : 'invalid_evidence_set',
  errors,
  expected_repository: expectedRepository,
  expected_commit_sha: expectedSha,
  expected_artifact_version: expectedVersion,
  available_files: [...names].sort(),
  unit_evidence_file: unitEvidence,
  unit_evidence_encoded: encodeURIComponent(unitEvidence),
  static_evidence_file: staticEvidence,
  static_evidence_encoded: encodeURIComponent(staticEvidence),
  dynamic_evidence_file: dynamicEvidence,
  dynamic_evidence_encoded: encodeURIComponent(dynamicEvidence)
};

const errors = [];

const value = {
  summary: <revisionreviewer.summary>,
  files: <revisionreviewer.files>,
  tests_expected: <revisionreviewer.tests_expected>,
  risks: <revisionreviewer.risks>,
  blocking_reason: <revisionreviewer.blocking_reason>
};

const allowedContext = Array.isArray(<buildrevisioncontext.result.files>)
  ? <buildrevisioncontext.result.files>
  : [];

const allowed = new Map(
  allowedContext.map((item) => [
    String(item.path),
    item
  ])
);

const approvedPaths =
  Array.isArray(<buildartifactcontext.result.approved_paths>)
    ? <buildartifactcontext.result.approved_paths>
    : [];

const approved = new Set(
  approvedPaths.map((path) => String(path))
);

const seen = new Set();
const files = [];

function normalizePath(input) {
  return String(input ?? '')
    .trim()
    .replace(/\\/g, '/')
    .replace(/^\.\//, '');
}

function isProtectedPath(path) {
  const normalized = path.toLowerCase();

  if (normalized === 'platform.md') {
    return true;
  }

  const protectedPrefixes = [
    '.git/',
    '.gitea/',
    '.github/',
    'ci/',
    'k8s/',
    'policies/',
    'secrets/'
  ];

  return protectedPrefixes.some((prefix) =>
    normalized.startsWith(prefix)
  );
}

const returnedFiles = Array.isArray(value.files)
  ? value.files
  : [];

for (const item of returnedFiles) {
  const path = normalizePath(item?.path);

  const content =
    typeof item?.content === 'string'
      ? item.content
      : null;

  if (!path) {
    errors.push('Revision Developer вернул пустой path');
    continue;
  }

  if (seen.has(path)) {
    errors.push(`Повторяющийся path: ${path}`);
    continue;
  }

  seen.add(path);

  if (isProtectedPath(path)) {
    errors.push(`Попытка изменить защищённый файл: ${path}`);
    continue;
  }

  if (!allowed.has(path)) {
    errors.push(
      `Файл не был разрешён CI Result Analyst: ${path}`
    );
    continue;
  }

  if (!approved.has(path)) {
    errors.push(
      `Файл отсутствует в утверждённом repository plan: ${path}`
    );
    continue;
  }

  if (content === null) {
    errors.push(
      `Содержимое файла должно быть строкой: ${path}`
    );
    continue;
  }

  if (content.length > 20000) {
    errors.push(
      `Содержимое файла слишком большое: ${path}`
    );
    continue;
  }

  if (/[\u3400-\u9fff]/u.test(content)) {
    errors.push(`Обнаружены китайские иероглифы в файле: ${path}`);
    continue;
  }
  if (/<\/?think>/iu.test(content)) {
    errors.push(`Обнаружен think tag в файле: ${path}`);
    continue;
  }

  const originalFile = allowed.get(path);

  if (content === originalFile.content) {
    errors.push(
      `Revision Developer не изменил файл: ${path}`
    );
    continue;
  }

  files.push({
    path,
    encoded_path: path
      .split('/')
      .map(encodeURIComponent)
      .join('/'),
    sha: String(originalFile.sha),
    content,
    reason: String(item?.reason ?? '')
  });
}

if (files.length === 0) {
  const blockingReason = String(value.blocking_reason ?? '').trim();
  if (blockingReason && !errors.includes(blockingReason)) {
    errors.push(blockingReason);
  } else if (errors.length === 0) {
    errors.push('Revision Developer не вернул файлов для исправления');
  }
}

return {
  valid: errors.length === 0,
  status: errors.length === 0
    ? 'revision_valid'
    : 'needs_human',
  errors,
  summary: String(value.summary ?? ''),
  files,
  tests_expected: Array.isArray(value.tests_expected)
    ? value.tests_expected.map(String)
    : [],
  risks: Array.isArray(value.risks)
    ? value.risks.map(String)
    : [],
  blocking_reason: String(value.blocking_reason ?? '')
};

const requested = Array.isArray(<normalizedecision.result.change_paths>)
  ? <normalizedecision.result.change_paths>
  : [];
const findings = Array.isArray(<normalizedecision.result.blocking_findings>)
  ? <normalizedecision.result.blocking_findings>
  : [];
const approvedList = Array.isArray(<buildartifactcontext.result.approved_paths>)
  ? <buildartifactcontext.result.approved_paths>
  : [];
const summary = <buildartifactcontext.result.summary>;
const evidence = <buildartifactcontext.result.evidence>;
const errors = [];
const warnings = [];
const selected = new Map();

function normalizePath(input) {
  return String(input ?? '')
    .trim()
    .replace(/\\/g, '/')
    .replace(/^file:\/\//i, '')
    .replace(/^\/workspace\//, '')
    .replace(/^\.\//, '')
    .replace(/:\d+(?::\d+)?$/, '');
}

function protectedPath(path) {
  const p = normalizePath(path).toLowerCase();
  return p === 'platform.md' ||
    p === '.git' || p.startsWith('.git/') ||
    p === '.gitea' || p.startsWith('.gitea/') ||
    p === '.github' || p.startsWith('.github/') ||
    p === 'ci' || p.startsWith('ci/') ||
    p === 'k8s' || p.startsWith('k8s/') ||
    p === 'policies' || p.startsWith('policies/') ||
    p === 'secrets' || p.startsWith('secrets/');
}

const approved = [...new Set(approvedList.map(normalizePath).filter(Boolean))];
const approvedSet = new Set(approved);

function addPath(raw, source) {
  const path = normalizePath(raw);
  if (!path || path.startsWith('/') || path.includes('\0') || path.split('/').includes('..')) {
    if (raw) warnings.push(`Пропущен небезопасный путь из ${source}: ${String(raw)}`);
    return;
  }
  if (protectedPath(path)) {
    warnings.push(`Защищённый путь оставлен вне автоисправления: ${path}`);
    return;
  }
  if (!approvedSet.has(path)) {
    warnings.push(`Путь из ${source} отсутствует в repository plan: ${path}`);
    return;
  }
  if (!selected.has(path)) selected.set(path, source);
}

for (const path of requested) addPath(path, 'решения аналитика');
for (const finding of findings) addPath(finding?.path, 'finding');

const evidenceText = [
  evidence?.unit?.content,
  evidence?.static?.content,
  evidence?.dynamic?.content,
  JSON.stringify(findings)
].map((item) => typeof item === 'string' ? item : JSON.stringify(item ?? '')).join('\n');

// Универсальный поиск: сверяем журнал с утверждёнными путями, поэтому не
// зависим от синтаксиса traceback конкретного языка или анализатора.
for (const path of approved) {
  if (evidenceText.includes(path) || evidenceText.includes(`/workspace/${path}`)) {
    addPath(path, 'доказательств CI');
  }
}

const stages = Array.isArray(summary?.stages) ? summary.stages : [];
const unitFailed = stages.some((item) => item?.category === 'unit' && item?.status !== 'passed');
const staticFailed = stages.some((item) => item?.category === 'static' && item?.status !== 'passed');
const runtimeFailed = stages.some((item) => item?.category === 'runtime' && item?.status !== 'passed');
const missingDependency = /ModuleNotFoundError|No module named|package not found|could not resolve|cannot find module/i.test(evidenceText);

function dependencyManifest(path) {
  return /^(?:requirements(?:-[^/]+)?\.txt|pyproject\.toml|poetry\.lock|pdm\.lock|uv\.lock|package(?:-lock)?\.json|pnpm-lock\.yaml|yarn\.lock|go\.(?:mod|sum)|Cargo\.(?:toml|lock)|pom\.xml|build\.gradle(?:\.kts)?)$/i.test(path);
}

function score(path) {
  const p = path.toLowerCase();
  let value = 0;
  if (/\.(?:py|js|jsx|ts|tsx|java|kt|kts|go|rs|cs|c|cc|cpp|h|hpp|rb|php|swift|scala|sh|sql|vue|svelte)$/.test(p)) value += 20;
  if (/^(?:tests?|spec|__tests__)\//.test(p) || /(?:^|\/)(?:test|spec)[_.-]/.test(p)) value += unitFailed ? 55 : 10;
  if (dependencyManifest(path)) value += missingDependency ? 70 : 5;
  if (/(?:^|\/)(?:main|app|server|index|bootstrap|entrypoint)[_.-]/.test(p)) value += runtimeFailed ? 45 : 10;
  if (/\.(?:json|ya?ml|toml|ini|cfg|conf)$/.test(p)) value += 8;
  if (staticFailed && !/^(?:docs?|examples?)\//.test(p)) value += 5;
  if (/\.(?:md|rst|txt)$/.test(p) && !dependencyManifest(path)) value -= 25;
  if (/\.(?:png|jpe?g|gif|pdf|zip|jar|exe|dll|so|bin)$/.test(p)) value -= 100;
  return value;
}

let fallbackUsed = false;
if (selected.size === 0) {
  fallbackUsed = true;
  const fallback = approved
    .filter((path) => !protectedPath(path))
    .map((path, index) => ({path, index, score: score(path)}))
    .sort((a, b) => b.score - a.score || a.index - b.index)
    .slice(0, 5);
  for (const item of fallback) addPath(item.path, 'ограниченного fallback-контекста');
  warnings.push(
    'CI не дал однозначного пути: выбраны наиболее релевантные файлы из repository plan; запись всё равно пройдёт финальную валидацию'
  );
}

let paths = [...selected.entries()].map(([path, source]) => ({
  path,
  encoded_path: path.split('/').map(encodeURIComponent).join('/'),
  source
}));
if (paths.length > 5) {
  warnings.push(`Набор контекста ограничен: ${paths.length} -> 5 файлов`);
  paths = paths.slice(0, 5);
}

if (approved.length === 0) errors.push('В development contract отсутствует repository_plan.files');
if (paths.length === 0) errors.push('Не удалось выбрать ни одного безопасного файла для анализа');

return {
  valid: errors.length === 0,
  status: errors.length === 0 ? 'scope_valid' : 'needs_human',
  errors,
  warnings,
  paths,
  requested_count: requested.length,
  selected_count: paths.length,
  approved_count: approved.length,
  fallback_used: fallbackUsed
};

const errors = [];

const value = {
  decision: <ciresultanalyst.decision>,
  summary: <ciresultanalyst.summary>,
  blocking_findings: <ciresultanalyst.blocking_findings>,
  change_paths: <ciresultanalyst.change_paths>,
  protected_findings: <ciresultanalyst.protected_findings>,
  confidence: <ciresultanalyst.confidence>
};

const allowedDecisions = new Set(['pass', 'revise', 'needs_human', 'reject']);
let decision = String(value.decision ?? '').trim();
let summary = String(value.summary ?? '');
let blockingFindings = Array.isArray(value.blocking_findings) ? value.blocking_findings : [];
const normalizationNotes = [];

function normalizePath(input) {
  return String(input ?? '')
    .trim()
    .replace(/\\/g, '/')
    .replace(/^file:\/\//i, '')
    .replace(/^\/workspace\//, '')
    .replace(/^\.\//, '')
    .replace(/:\d+(?::\d+)?$/, '');
}

function protectedPath(path) {
  const p = normalizePath(path).toLowerCase();
  return p === 'platform.md' ||
    p === '.git' || p.startsWith('.git/') ||
    p === '.gitea' || p.startsWith('.gitea/') ||
    p === '.github' || p.startsWith('.github/') ||
    p === 'ci' || p.startsWith('ci/') ||
    p === 'k8s' || p.startsWith('k8s/') ||
    p === 'policies' || p.startsWith('policies/') ||
    p === 'secrets' || p.startsWith('secrets/');
}

function isDependencyManifest(path) {
  return /^(?:requirements(?:-[^/]+)?\.txt|pyproject\.toml|poetry\.lock|pdm\.lock|uv\.lock|package(?:-lock)?\.json|pnpm-lock\.yaml|yarn\.lock|go\.(?:mod|sum)|Cargo\.(?:toml|lock)|pom\.xml|build\.gradle(?:\.kts)?)$/i.test(path);
}

const approved = [...new Set(
  (Array.isArray(<buildartifactcontext.result.approved_paths>)
    ? <buildartifactcontext.result.approved_paths>
    : [])
    .map(normalizePath)
    .filter((path) => path && !protectedPath(path))
)];
const approvedSet = new Set(approved);

const evidenceParts = [
  <buildartifactcontext.result.evidence.unit.content>,
  <buildartifactcontext.result.evidence.static.content>,
  <buildartifactcontext.result.evidence.dynamic.content>,
  JSON.stringify(blockingFindings)
].map((item) => typeof item === 'string' ? item : JSON.stringify(item ?? ''));
const evidenceText = evidenceParts.join('\n');

const evidencePaths = approved.filter((path) =>
  evidenceText.includes(path) || evidenceText.includes(`/workspace/${path}`)
);

let paths = Array.isArray(value.change_paths)
  ? [...new Set(value.change_paths.map(normalizePath).filter(Boolean))]
  : [];
const modelSelectedOnlyManifests = paths.length > 0 && paths.every(isDependencyManifest);

// Пути, явно названные findings/traceback, надёжнее предположений модели.
for (const finding of blockingFindings) {
  const path = normalizePath(finding?.path);
  if (approvedSet.has(path) && !paths.includes(path)) paths.push(path);
}
for (const path of evidencePaths) {
  if (!paths.includes(path)) paths.push(path);
}

const unitEvidence = String(<buildartifactcontext.result.evidence.unit.content> ?? '');
const symbolImport = unitEvidence.match(
  /ImportError:\s+cannot import name\s+['\"]([^'\"]+)['\"]\s+from\s+['\"]([^'\"]+)['\"]/i
);

function tracebackTestPath(text) {
  const matches = [
    ...text.matchAll(/(?:^|\n)(?:\/workspace\/)?([A-Za-z0-9_.-]+(?:\/[A-Za-z0-9_.-]+)+):(\d+):\s+in\s+/gm)
  ];
  for (let index = matches.length - 1; index >= 0; index -= 1) {
    const path = normalizePath(matches[index][1]);
    if ((path.startsWith('tests/') || path.startsWith('test/')) && approvedSet.has(path)) {
      return {path, line: Number(matches[index][2] ?? 0)};
    }
  }
  return null;
}

if (decision === 'revise' && symbolImport && modelSelectedOnlyManifests) {
  const source = tracebackTestPath(unitEvidence);
  const symbol = String(symbolImport[1]);
  const moduleName = String(symbolImport[2]);
  if (source) {
    paths = [source.path];
    summary =
      `Автоматически уточнён диагноз: модуль ${moduleName} загружен, ` +
      `но не экспортирует ${symbol}. Требуется исправить импорт в ${source.path}.`;
    blockingFindings = blockingFindings.map((item) =>
      String(item?.tool ?? '').toLowerCase() === 'pytest'
        ? {
            ...item,
            path: source.path,
            line: source.line,
            reason:
              `Модуль ${moduleName} найден, но символ ${symbol} импортируется ` +
              'из неверного модуля; это не отсутствующая зависимость.'
          }
        : item
    );
    normalizationNotes.push(
      `dependency manifest заменён на ${source.path}: cannot-import-name не является ModuleNotFoundError`
    );
  }
}

const attempt = Number(<validateinput.result.attempt>);
const maxAttempts = Number(<validateinput.result.max_attempts>);

// Если модель слишком рано выбрала needs_human, но CI прямо назвал
// утверждённые application-файлы, разрешаем безопасную попытку revise.
if (decision === 'needs_human' && attempt <= maxAttempts && evidencePaths.length > 0) {
  decision = 'revise';
  paths = evidencePaths.slice(0, 20);
  summary =
    'Автоматическая восстановительная попытка: CI содержит ссылки на ' +
    `утверждённые файлы ${paths.join(', ')}. Файлы будут прочитаны до изменения.`;
  normalizationNotes.push('needs_human преобразован в ограниченный revise по доказанным путям');
}

if (!allowedDecisions.has(decision)) {
  if (evidencePaths.length > 0 && attempt <= maxAttempts) {
    decision = 'revise';
    paths = evidencePaths.slice(0, 20);
    normalizationNotes.push('Неизвестное решение аналитика восстановлено по путям из CI');
  } else {
    decision = 'needs_human';
    paths = [];
    normalizationNotes.push('Неизвестное решение аналитика безопасно сведено к needs_human');
  }
}

if (decision === 'revise' && attempt > maxAttempts) {
  decision = 'needs_human';
  paths = [];
  summary =
    `Исчерпан лимит внешних CI-итераций: ${maxAttempts}. ` +
    `Последнее заключение: ${summary}`;
}

if (decision === 'revise') {
  paths = [...new Set(paths.map(normalizePath).filter(Boolean))].slice(0, 20);
  if (paths.length === 0) {
    // Select Revision Paths выполнит ограниченный fallback по repository plan.
    normalizationNotes.push('Аналитик не дал путь; разрешён fallback выбора контекста');
  }
} else {
  paths = [];
}

return {
  valid: true,
  status: decision,
  errors,
  decision,
  summary,
  blocking_findings: blockingFindings,
  change_paths: paths,
  protected_findings: Array.isArray(value.protected_findings)
    ? value.protected_findings.map(String)
    : [],
  confidence: Number(value.confidence ?? 0),
  normalization_notes: normalizationNotes,
  evidence_paths: evidencePaths,
  attempt,
  max_attempts: maxAttempts
};

const errors = [];

const value = {
  summary: <revisiondeveloper.summary>,
  files: <revisiondeveloper.files>,
  tests_expected: <revisiondeveloper.tests_expected>,
  risks: <revisiondeveloper.risks>,
  blocking_reason: <revisiondeveloper.blocking_reason>
};

const allowedContext = Array.isArray(<buildrevisioncontext.result.files>)
  ? <buildrevisioncontext.result.files>
