);

const approvedPaths =
  Array.isArray(<buildartifactcontext.result.approved_paths>)
    ? <buildartifactcontext.result.approved_paths>
    : [];

const approved = new Set(
  approvedPaths.map((path) => String(path))
);

const seen = new Set();
const files = [];

function normalizePath(input) {
  return String(input ?? '')
    .trim()
    .replace(/\\/g, '/')
    .replace(/^\.\//, '');
}

function isProtectedPath(path) {
  const normalized = path.toLowerCase();

  if (normalized === 'platform.md') {
    return true;
  }

  const protectedPrefixes = [
    '.git/',
    '.gitea/',
    '.github/',
    'ci/',
    'k8s/',
    'policies/',
    'secrets/'
  ];

  return protectedPrefixes.some((prefix) =>
    normalized.startsWith(prefix)
  );
}

const returnedFiles = Array.isArray(value.files)
  ? value.files
  : [];

for (const item of returnedFiles) {
  const path = normalizePath(item?.path);

  const content =
    typeof item?.content === 'string'
      ? item.content
      : null;

  if (!path) {
    errors.push('Revision Developer вернул пустой path');
    continue;
  }

  if (seen.has(path)) {
    errors.push(`Повторяющийся path: ${path}`);
    continue;
  }

  seen.add(path);

  if (isProtectedPath(path)) {
    errors.push(`Попытка изменить защищённый файл: ${path}`);
    continue;
  }

  if (!allowed.has(path)) {
    errors.push(
      `Файл не был разрешён CI Result Analyst: ${path}`
    );
    continue;
  }

  if (!approved.has(path)) {
    errors.push(
      `Файл отсутствует в утверждённом repository plan: ${path}`
    );
    continue;
  }

  if (content === null) {
    errors.push(
      `Содержимое файла должно быть строкой: ${path}`
    );
    continue;
  }

  if (content.length > 20000) {
    errors.push(
      `Содержимое файла слишком большое: ${path}`
    );
    continue;
  }

  if (/[\u3400-\u9fff]/u.test(content)) {
    errors.push(`Обнаружены китайские иероглифы в файле: ${path}`);
    continue;
  }
  if (/<\/?think>/iu.test(content)) {
    errors.push(`Обнаружен think tag в файле: ${path}`);
    continue;
  }

  const originalFile = allowed.get(path);

  if (content === originalFile.content) {
    errors.push(
      `Revision Developer не изменил файл: ${path}`
    );
    continue;
  }

  files.push({
    path,
    encoded_path: path
      .split('/')
      .map(encodeURIComponent)
      .join('/'),
    sha: String(originalFile.sha),
    content,
    reason: String(item?.reason ?? '')
  });
}

if (files.length === 0) {
  const blockingReason = String(value.blocking_reason ?? '').trim();
  if (blockingReason && !errors.includes(blockingReason)) {
    errors.push(blockingReason);
  } else if (errors.length === 0) {
    errors.push('Revision Developer не вернул файлов для исправления');
  }
}

return {
  valid: errors.length === 0,
  status: errors.length === 0
    ? 'draft_valid'
    : 'draft_invalid',
  errors,
  summary: String(value.summary ?? ''),
  files,
  tests_expected: Array.isArray(value.tests_expected)
    ? value.tests_expected.map(String)
    : [],
  risks: Array.isArray(value.risks)
    ? value.risks.map(String)
    : [],
  blocking_reason: String(value.blocking_reason ?? '')
};

const errors = [];

function text(value) { return String(value ?? '').trim(); }
function safeName(value) { return /^[A-Za-z0-9_.-]{1,100}$/.test(value); }

const runId = text(<start.run_id>);
const owner = text(<start.owner>);
const repo = text(<start.repo>);
