if (`${owner}/${repo}` !== 'labadmin/demo-fastapi') errors.push('repository отсутствует в FastAPI production allowlist');
if (!branch || branch.length > 200 || /[\s~^:?*\\[]/.test(branch) || branch.includes('..')) {
