  artifact_package: artifactPackage,
  artifact_version: artifactVersion,
  artifact_version_encoded: encodeURIComponent(artifactVersion),
  context_owner: contextOwner,
  context_package: contextPackage,
  context_version: contextVersion,
  context_version_encoded: encodeURIComponent(contextVersion),
  attempt,
  max_attempts: 5,
  dry_run: dryRun,
  architecture_artifact: null,
  approved_paths: []
};

const files = <validatefinalrevision.result.files>;

function utf8ToBase64(value) {
  const text = String(value ?? ''); const bytes = [];
  for (let i = 0; i < text.length; i++) {
    let cp = text.charCodeAt(i);
    if (cp >= 0xd800 && cp <= 0xdbff) {
      const next = text.charCodeAt(i + 1);
      if (next >= 0xdc00 && next <= 0xdfff) { cp = 0x10000 + ((cp - 0xd800) << 10) + (next - 0xdc00); i++; }
      else cp = 0xfffd;
    } else if (cp >= 0xdc00 && cp <= 0xdfff) cp = 0xfffd;
    if (cp <= 0x7f) bytes.push(cp);
    else if (cp <= 0x7ff) bytes.push(0xc0 | (cp >> 6), 0x80 | (cp & 0x3f));
    else if (cp <= 0xffff) bytes.push(0xe0 | (cp >> 12), 0x80 | ((cp >> 6) & 0x3f), 0x80 | (cp & 0x3f));
    else bytes.push(0xf0 | (cp >> 18), 0x80 | ((cp >> 12) & 0x3f), 0x80 | ((cp >> 6) & 0x3f), 0x80 | (cp & 0x3f));
  }
  const alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'; let result = '';
  for (let i = 0; i < bytes.length; i += 3) {
    const a = bytes[i], hasB = i + 1 < bytes.length, hasC = i + 2 < bytes.length;
    const b = hasB ? bytes[i + 1] : 0, c = hasC ? bytes[i + 2] : 0;
    result += alphabet[a >> 2]; result += alphabet[((a & 3) << 4) | (b >> 4)];
    result += hasB ? alphabet[((b & 15) << 2) | (c >> 6)] : '=';
    result += hasC ? alphabet[c & 63] : '=';
  }
  return result;
}

const updateFiles = files.map((item) => ({...item, content_base64: utf8ToBase64(item.content)}));
return {
  status: <validateinput.result.dry_run> ? 'dry_run_ready' : 'write_ready',
  dry_run: <validateinput.result.dry_run>,
  update_files: updateFiles,
  file_count: updateFiles.length,
  summary: <validatefinalrevision.result.summary>,
  attempt: <validateinput.result.attempt>,
  next_attempt: Number(<validateinput.result.attempt>) + 1,
  protected_findings: <normalizedecision.result.protected_findings>
};

function parseData(value) {
  if (value && typeof value === 'object') return value;
  if (typeof value !== 'string' || !value.trim()) return null;
  try { return JSON.parse(value); } catch (_) { return value; }
}

function truncate(value, limit) {
  const text = typeof value === 'string' ? value : JSON.stringify(value ?? null);
  return text.length <= limit ? text : text.slice(0, limit) + '\n...[обрезано Workflow 04]';
}

const errors = [];
const resolved = <resolveartifactevidence.result>;
const summary = parseData(<getcisummary.data>);
const findingsRaw = parseData(<getfindings.data>);
