}
if (Number(<getunitevidence.status>) !== 200) errors.push('Не получено доказательство этапа тестирования');
if (Number(<getstaticevidence.status>) !== 200) errors.push('Не получено доказательство статического анализа');
if (Number(<getdynamicevidence.status>) !== 200) errors.push('Не получено доказательство динамического анализа');

const developmentContract =
