}

const contractOwner = String(developmentContract?.owner ?? '');
const contractRepo = String(developmentContract?.repo ?? '');
if (developmentContract && (contractOwner !== String(<validateinput.result.owner> ?? '') || contractRepo !== String(<validateinput.result.repo> ?? ''))) {
