      .map((item) => String(item ?? '').trim().replace(/^\.\//, ''))
      .filter(Boolean))]
  : [];
if (approvedPaths.length === 0) {
  errors.push('В development contract отсутствует непустой repository_plan.files');
}

const evidence = {
  unit: {
