return {
  valid: errors.length === 0,
  status: errors.length === 0 ? 'artifacts_valid' : 'invalid_artifacts',
  errors,
  summary,
  findings: Array.isArray(findingsRaw) ? findingsRaw : [],
  manifest,
  development_contract: developmentContract,
  approved_paths: approvedPaths,
  evidence,
  source_statuses: {
    summary: Number(<getcisummary.status>),
    findings: Number(<getfindings.status>),
    manifest: Number(<getmanifest.status>),
    development_contract: Number(<getdevelopmentcontract.status>),
    unit_evidence: Number(<getunitevidence.status>),
    static_evidence: Number(<getstaticevidence.status>),
    dynamic_evidence: Number(<getdynamicevidence.status>)
  }
};

const requested = <selectrevisionpaths.result.paths>;
const iterations = <readrevisionfiles.results>;
const files = [];
const errors = [];
let totalChars = 0;

function decodeUtf8(bytes) {
  let result = '';
  for (let i = 0; i < bytes.length;) {
    const first = bytes[i++];
    if (first <= 0x7f) { result += String.fromCharCode(first); continue; }
    let codePoint, count, minimum;
    if ((first & 0xe0) === 0xc0) { codePoint = first & 0x1f; count = 1; minimum = 0x80; }
    else if ((first & 0xf0) === 0xe0) { codePoint = first & 0x0f; count = 2; minimum = 0x800; }
    else if ((first & 0xf8) === 0xf0) { codePoint = first & 0x07; count = 3; minimum = 0x10000; }
    else { result += '\uFFFD'; continue; }
    if (i + count > bytes.length) { result += '\uFFFD'; break; }
    let valid = true;
    for (let j = 0; j < count; j++) {
      const next = bytes[i];
      if ((next & 0xc0) !== 0x80) { valid = false; break; }
      i++; codePoint = (codePoint << 6) | (next & 0x3f);
    }
    if (!valid || codePoint < minimum || codePoint > 0x10ffff || (codePoint >= 0xd800 && codePoint <= 0xdfff)) {
      result += '\uFFFD'; continue;
    }
    if (codePoint <= 0xffff) result += String.fromCharCode(codePoint);
    else {
      const adjusted = codePoint - 0x10000;
      result += String.fromCharCode(0xd800 + (adjusted >> 10), 0xdc00 + (adjusted & 0x3ff));
    }
  }
  return result;
}

function decodeBase64Utf8(value) {
  const alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
  let encoded = String(value ?? '').replace(/\s/g, '');
  if (!encoded) return '';
  const paddingAt = encoded.indexOf('=');
  if (paddingAt !== -1) encoded = encoded.slice(0, paddingAt);
  if (/[^A-Za-z0-9+/]/.test(encoded) || encoded.length % 4 === 1) throw new Error('invalid Base64');
  const bytes = [];
  for (let i = 0; i < encoded.length; i += 4) {
    const a = alphabet.indexOf(encoded[i]); const b = alphabet.indexOf(encoded[i + 1]);
    const c = i + 2 < encoded.length ? alphabet.indexOf(encoded[i + 2]) : -1;
    const d = i + 3 < encoded.length ? alphabet.indexOf(encoded[i + 3]) : -1;
    if (a < 0 || b < 0) throw new Error('invalid Base64 quartet');
    bytes.push((a << 2) | (b >> 4));
    if (c >= 0) bytes.push(((b & 15) << 4) | (c >> 2));
    if (d >= 0) bytes.push(((c & 3) << 6) | d);
  }
  return decodeUtf8(bytes);
}

for (let i = 0; i < (Array.isArray(requested) ? requested.length : 0); i++) {
  const path = String(requested[i]?.path ?? '');
  const outputs = Array.isArray(iterations?.[i]) ? iterations[i] : [];
  const apiOutput = outputs.find((item) => item && Object.prototype.hasOwnProperty.call(item, 'data'));
  const data = apiOutput?.data;
  if (!data || data.type !== 'file' || !data.sha) { errors.push(`Не удалось прочитать ${path}`); continue; }
  try {
    const content = decodeBase64Utf8(data.content);
    if (content.length > 20000) { errors.push(`Файл слишком большой: ${path}`); continue; }
    totalChars += content.length;
    files.push({path, sha: String(data.sha), content});
  } catch (error) { errors.push(`Ошибка декодирования ${path}: ${String(error?.message ?? error)}`); }
}
if (totalChars > 30000) errors.push('Суммарный контекст превышает 30000 символов');

return {
  valid: errors.length === 0 && files.length === requested.length,
  status: errors.length === 0 ? 'repository_context_valid' : 'repository_context_invalid',
  errors,
  files,
  count: files.length,
  total_chars: totalChars
};

